from layout import *

def dense():
    page('Независимый способ извлекать память','Перенос короткой записи на плотный поиск BGE',
         'Проверили, переносится ли результат по адресам на публичный энкодер, который использовали авторы SERBench. Модель и оценщик фиксированы во всех строках.')
    p('BAAI/bge-large-en-v1.5 получил один и тот же набор кандидатов для каждого из 500 состояний Cal500. Каждый кандидат — путь и отрывок кода. Запрос описывал только issue либо дополнялся текущей потребностью и подцелью. В ограниченных вариантах к тому же запросу добавлялись до 192 токенов записки. Для BGE применён нативный лимит 512 токенов и штатное нормализованное CLS-представление. После одного кодирования использовали косинусную близость без дополнительных запросов к LLM.')
    d=J('serbench/dense_results.json');m=d['arms'];r=d['contrasts']['addresses minus tail']['mss_complete@5']
    tbl(['Запрос BGE на Cal500','Полнота @5','Полнота @8'],[[name,perc(m[k]['mss_complete@5']),perc(m[k]['mss_complete@8'])] for k,name in [('issue','Только описание задачи'),('state','Описание, текущая потребность и подцель'),('tail','Дополнительно конец истории'),('arguments','Дополнительно аргументы действий'),('addresses','Дополнительно пути, строки и аргументы'),('fusion_tail','Слияние рангов состояния и хвоста'),('fusion_arguments','Слияние рангов состояния и аргументов'),('fusion_addresses','Слияние рангов состояния и адресов')]], [9.5,3.8,3.8],True)
    p(f"В сравнении с концом истории адресная запись по основному исходу @5 дала {r['W']} выигрышей и {r['L']} проигрышей, разность {pp(r['delta'],2)} п.п. (95% ДИ по репозиториям от {pp(r['ci'][0],2)} до {pp(r['ci'][1],2)}).")
    r2=d['contrasts']['addresses minus arguments']['mss_complete@5'];r3=d['contrasts']['addresses minus state']['mss_complete@5']
    p(f"Против аргументов без адресов разность при пяти объектах {pp(r2['delta'],2)} п.п. Относительно состояния без записи — {pp(r3['delta'],2)} п.п. Слияние усредняет обратные ранги исходного и дополненного запросов с константой 60. Применена прежняя фиксированная политика записи без дообучения BGE или подбора веса на этой таблице.")
    h('Контроль вытеснения и подмена памяти')
    p('Во всех ветвях оставили те же первые до 252 токенов текущего задания. Дописали до 255 токенов записки. По @5 собственные адреса дали 31,2%, аргументы 31,8%, конец истории 28,6%, чужие адреса из другого проекта 30,4%, пустая запись 29,8%. Разность между своими и чужими адресами +0,8 п.п. (95% ДИ от −2,43 до +4,04). Приоритет вопроса меняет результат. Специфическая польза собственных адресов остаётся недоказанной.')
    runtime=J('serbench/dense_runtime.json')
    p(f"Фактический прогон — {n(runtime['count'])} уникальных входных текстов на {runtime['gpu']}. Для BGE в самой статье опубликованы 31,0% и 40,8% на закрытом Test500. Иная выборка, формулировка запроса и токенизация препятствуют прямому сопоставлению уровней. Здесь проверен перенос одного механизма на одном и том же наборе и опубликованном типе читателя.")
    source('BGE-large-en-v1.5 · точный снимок модели BAAI','https://huggingface.co/BAAI/bge-large-en-v1.5/tree/d4aa6901d3a41ba39fb536a557fa166f842b0e09')
    source('Feng et al. · результаты BGE и семантического метода на закрытой части',ar('2609.20050'))
